mapper.select:
SELECT id
FROM interview_session
WHERE user_id = #{userId}
  AND status = 0
  AND is_deleted = 0
  AND update_time < #{cutoff}
ORDER BY update_time ASC
LIMIT #{limit}

mapper.update:
UPDATE interview_session
SET status = #{status}
WHERE id = #{id} AND is_deleted = 0
